{"hypothesis":"Replacing randomly ordered cut trials with a coarse-to-fine beam search will find better repairable reflections and improve the verified score by at least 1e-5.","rationale":"The previous search spent its topology budget on unrelated cuts and produced only numerical-scale gains. Refining several promising cut neighborhoods before packet-weight repair should distinguish a narrow useful rearrangement from an effectively unchanged endpoint cut, while retaining exact-score acceptance.","source":"import time
import numpy as np
import scipy.fft as fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize

PARAMS = {
    'search_fraction': (0.43, 0.15, 0.55),
    'total_fraction': (0.70, 0.50, 0.73),
    'repair_tolerance': (0.0003, 0.000001, 0.01, 'log'),
    'beta': (3e8, 1e6, 1e11, 'log'),
    'beam_width': (4, 2, 10),
    'coarse_cuts': (9, 5, 24),
}


def decode(obj):
    if 'values' in obj:
        return np.maximum(np.asarray(obj['values'], dtype=float), 0.0)
    a = np.maximum(np.asarray(obj['ring'], dtype=float), 0.0)
    k = int(obj.get('cut', 0))
    mode = int(obj.get('reflection', 0))
    if mode == 1:
        return np.concatenate((a[:k][::-1], a[k:]))
    if mode == 2:
        return np.concatenate((a[:k], a[k:][::-1]))
    return np.concatenate((a[k:], a[:k])) if k else a.copy()


def exact_score(f):
    c = oaconvolve(f, f, mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.concatenate(([0.0], c, [0.0]))
    a, b = y[:-1], y[1:]
    num = float(np.sum((np.diff(x) / 3.0) * (a*a + a*b + b*b)))
    return float(num / ((np.sum(np.abs(c)) / (len(c)+1)) * np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['total_fraction']) * budget_s
    search_end = start + float(params['search_fraction']) * budget_s
    if init is None:
        return {'values': [1.0]}
    f0 = decode(init)
    baseline = exact_score(f0)
    n = len(f0)
    if n < 4 or time.monotonic() >= deadline:
        return init
    rng = np.random.default_rng(seed)
    f0 = f0 / float(f0.max())
    m = fft.next_fast_len(2*n-1, real=True)
    best_score = baseline
    best_f = None
    contender = None
    contender_score = -np.inf
    tested = set()
    records = []

    def make(k, mode):
        if mode == 0:
            return np.concatenate((f0[k:], f0[:k]))
        if mode == 1:
            return np.concatenate((f0[:k][::-1], f0[k:]))
        return np.concatenate((f0[:k], f0[k:][::-1]))

    def inspect(k, mode):
        nonlocal best_score, best_f, contender, contender_score
        k = int(k)
        if not 0 < k < n or (k, mode) in tested or time.monotonic() >= search_end:
            return
        tested.add((k, mode))
        f = make(k, mode)
        sp = fft.rfft(f, m)
        c = fft.irfft(sp*sp, m)[:2*n-1]
        score = float((2*np.dot(c,c)+np.dot(c[:-1],c[1:])) /
                      (3*np.sum(np.abs(c))*np.max(np.abs(c))))
        records.append((score, k, mode))
        if score > contender_score:
            contender_score = score
            contender = f
        if score > best_score - 2e-13 and time.monotonic() < deadline-1.2:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()

    # First screen a small, deterministic covering of mass and support gaps.
    cumulative = np.cumsum(f0)
    count = int(params['coarse_cuts'])
    cuts = set(np.searchsorted(cumulative, np.linspace(0.025, 0.975, count)*cumulative[-1]).tolist())
    occupied = f0 > 0
    changes = np.flatnonzero(occupied[1:] != occupied[:-1]) + 1
    edges = np.r_[0, changes, n]
    widths = np.diff(edges)
    for j in np.argsort(widths)[::-1][:6]:
        if time.monotonic() >= search_end:
            break
        if not occupied[edges[j]]:
            cuts.add(int((edges[j]+edges[j+1])//2))
    jobs = [(int(k), mode) for k in sorted(cuts) for mode in (0, 1, 2)]
    rng.shuffle(jobs)
    coarse_end = start + 0.53*(search_end-start)
    for k, mode in jobs:
        if time.monotonic() >= coarse_end:
            break
        inspect(k, mode)

    # Refine multiple separated basins, rather than spending the remainder
    # on unrelated cuts. Snap one proposal to an actual support boundary.
    radius = max(1, n//24)
    while time.monotonic() < search_end and records:
        beam = []
        for item in sorted(records, reverse=True):
            if time.monotonic() >= search_end:
                break
            _, k, mode = item
            if all(mode != old[2] or abs(k-old[1]) > max(1, radius//2) for old in beam):
                beam.append(item)
            if len(beam) >= int(params['beam_width']):
                break
        before = len(tested)
        for _, k, mode in beam:
            if time.monotonic() >= search_end:
                break
            proposals = [k-radius, k+radius]
            if len(changes):
                j = int(np.searchsorted(changes, k))
                proposals.append(int(changes[min(j, len(changes)-1)]))
                proposals.append(int(changes[max(0, j-1)]))
            for q in proposals:
                if time.monotonic() >= search_end:
                    break
                inspect(q, mode)
        if radius == 1:
            break
        radius = max(1, radius//4)
        if len(tested) == before and radius == 1:
            break

    if contender is None or contender_score < baseline-float(params['repair_tolerance']) or time.monotonic() >= deadline-1.5:
        return init if best_f is None else {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}

    base = contender
    spec = fft.rfft(base, m)
    peak = fft.irfft(spec*spec, m)[:2*n-1].max()
    base = base / np.sqrt(peak)
    indices = np.flatnonzero(base > 0)
    starts = np.r_[True, (np.diff(indices) != 1) | (indices[1:]//256 != indices[:-1]//256)]
    labels = np.cumsum(starts, dtype=np.int64)-1
    groups = int(labels[-1])+1
    active = base[indices]
    beta = float(params['beta'])

    class Stop(Exception):
        pass

    def objective(x):
        nonlocal best_score, best_f
        if time.monotonic() >= deadline-1.5:
            raise Stop()
        f = np.zeros(n)
        f[indices] = active*np.square(x[labels])
        sp = fft.rfft(f, m)
        c = fft.irfft(sp*sp, m)[:2*n-1]
        peak = c.max()
        e = np.exp(beta*(c-peak))
        z = e.sum()
        smooth = peak + np.log(z)/beta
        num = (2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/3
        total = f.sum()
        quick = num/(np.sum(np.abs(c))*np.max(np.abs(c)))
        if quick > best_score+1e-13 and time.monotonic() < deadline-1.0:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        g = 4*c
        g[1:] += c[:-1]
        g[:-1] += c[1:]
        g /= 3*num
        g -= e/(z*smooth)
        corr = fft.irfft(fft.rfft(g,m)*np.conj(sp),m)[:n]
        local = (2*corr[indices]-2/total)*active
        grad = 2*x*np.bincount(labels, weights=local, minlength=groups)
        value = np.log(num)-2*np.log(total)-np.log(smooth)
        return -value, -grad

    try:
        minimize(objective, np.ones(groups), jac=True, method='L-BFGS-B',
                 options={'maxcor': 7, 'maxiter': 10000, 'maxfun': 20000,
                          'ftol': 0.0, 'gtol': 0.0, 'maxls': 15})
    except Stop:
        pass
    if best_f is None:
        return init
    return {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}
"}
